<script setup>
import {formatarAlvo,formatarNumero} from '../utils/format.js'
import { computed, ref, watch } from 'vue'
import { apiGet } from '../services/api.js'
import { useLatestQuery } from '../composables/useLatestQuery.js'
import { formatDateTime, formatDate } from '../utils/workflow.js'
import { label } from '../utils.js'
import AppIcon from './AppIcon.vue'
import RecordText from './RecordText.vue'
const props = defineProps({ patientId: { type: Number, required: true }, refreshKey: { type: Number, default: 0 }, compact: Boolean, busy: Boolean })
const emit = defineEmits(['navigate'])
const query = useLatestQuery((options, id) => apiGet(`/clinical/patients/${id}/summary`, options))
const { data: summary, loading, error } = query
const expanded = ref(!props.compact)
const plan = computed(() => summary.value?.plans.focus)
const stamp = formatDateTime
const value = reading => reading.value_num==null?reading.value_category:formatarNumero(reading.value_num,2)
function open(section, planId, indicatorId) { emit('navigate', { section, planId, indicatorId }) }
watch(() => [props.patientId, props.refreshKey], () => { query.cancel(true); query.run(props.patientId) }, { immediate: true })
watch(() => props.compact, compact => { expanded.value = !compact })
</script>
<template>
  <section class="card card-body patient-summary mb-4" aria-labelledby="patient-summary-title" :aria-busy="loading" data-testid="patient-summary">
    <header class="summary-heading"><div><div class="d-flex align-items-center gap-2 mb-1"><AppIcon name="heart" :size="20" /><h2 id="patient-summary-title" class="h5 mb-0">Resumo do prontuário</h2></div><p class="small text-secondary mb-0">{{ summary ? 'Registros consultados em ' + stamp(summary.generated_at) : 'Reunindo os registros deste paciente…' }}</p></div><div class="d-flex gap-2"><button class="btn btn-sm btn-outline-secondary" :disabled="loading" @click="query.run(patientId)" aria-label="Atualizar resumo do prontuário"><AppIcon name="cycle" :size="16" /></button><button v-if="summary" class="btn btn-sm btn-outline-success" :aria-expanded="expanded" @click="expanded = !expanded">{{ expanded ? 'Recolher detalhes' : 'Ver resumo completo' }}</button></div></header>
    <p v-if="error" class="alert alert-danger mt-3 mb-0" role="alert">Não foi possível carregar o resumo. {{ error }} <button class="btn btn-sm btn-link" @click="query.run(patientId)">Tentar novamente</button></p>
    <div v-else-if="loading && !summary" class="loading-state py-4" role="status"><span class="spinner-border spinner-border-sm" /> Consultando os registros autorizados…</div>
    <template v-if="summary">
      <p v-if="summary.clinical_return?.available" class="small mb-3"><strong>Risco confirmado: {{ summary.clinical_return.risk }}</strong> · retorno devido {{ formatDate(summary.clinical_return.due_date) }} · {{ summary.clinical_return.doctor_name }}</p>
      <div class="summary-facts"><div><span>Último comparecimento registrado</span><strong>{{ summary.last_attended ? stamp(summary.last_attended.scheduled_at) : 'Sem registro de comparecimento' }}</strong><small>{{ summary.last_attended?.professional_name || 'Consulta prevista não é considerada realizada.' }}</small></div><div><span>Próximo atendimento</span><strong>{{ summary.next_appointment ? stamp(summary.next_appointment.scheduled_at) : 'Nenhum retorno programado' }}</strong><small>{{ summary.next_appointment ? summary.next_appointment.professional_name + ' · ' + label(summary.next_appointment.status) : 'Verifique a programação de continuidade.' }}</small></div><div><span>Reavaliação do plano</span><strong>{{ summary.reassessment ? formatDate(summary.reassessment.date) : 'Sem data em plano ativo/revisado' }}</strong><small :class="{ 'text-warning-emphasis': summary.reassessment?.overdue }">{{ summary.reassessment?.overdue ? 'Data prevista já passou; revisar programação.' : summary.reassessment ? 'Data prevista pelo profissional.' : 'Nenhuma data é presumida.' }}</small></div><div><span>Plano em destaque</span><strong>{{ plan ? label(plan.status) : 'Sem plano registrado' }}</strong><small>{{ plan?.professional_name }}<br>{{ summary.goals.total }} meta(s) em acompanhamento · {{ summary.unconfirmed_returns }} retorno(s) sem confirmação</small></div></div>
      <div v-if="expanded" class="summary-details">
        <div class="summary-clinical-grid"><article class="summary-block"><div class="section-heading mb-3"><h3 class="h6 mb-0">Plano em destaque</h3><span v-if="plan" class="status-badge" :class="plan.status">{{ label(plan.status) }}</span></div><template v-if="plan"><p class="summary-authorship">{{ plan.professional_name }} · {{ plan.team_name }}<br>Início: {{ formatDate(plan.start_date) }}</p><h4 class="summary-label">Objetivos registrados</h4><RecordText :text="plan.objectives" /><h4 class="summary-label mt-3">Observações clínicas restritas</h4><RecordText :text="plan.clinical_notes" empty="Nenhuma observação clínica registrada neste plano." /><button class="btn btn-link btn-sm p-0 mt-3" :disabled="busy" @click="open('plan', plan.id)">Ver plano e intervenções <AppIcon name="arrow" :size="15" /></button><p v-if="summary.plans.active > 1" class="small text-secondary mt-2 mb-0">Há {{ summary.plans.active }} planos ativos. O destaque usa a reavaliação prevista mais próxima.</p></template><p v-else class="text-secondary mb-0">Ainda não há plano de cuidado registrado.</p></article>
        <article class="summary-block"><div class="section-heading mb-3"><h3 class="h6 mb-0">Última evolução registrada</h3><span v-if="summary.latest_evolution" class="soft-tag">{{ label(summary.latest_evolution.kind) }}</span></div><template v-if="summary.latest_evolution"><p class="summary-authorship">{{ summary.latest_evolution.author_name }} · {{ stamp(summary.latest_evolution.created_at) }}</p><RecordText :text="summary.latest_evolution.notes" :limit="320" /><button class="btn btn-link btn-sm p-0 mt-3" :disabled="busy" @click="open('records', summary.latest_evolution.plan_id)">Ver registro e histórico <AppIcon name="arrow" :size="15" /></button></template><p v-else class="text-secondary mb-0">Nenhuma evolução profissional registrada.</p><div v-if="summary.latest_adherence" class="summary-adherence"><h4 class="summary-label">Última ação pactuada registrada</h4><p class="small mb-1">{{ summary.latest_adherence.action_description }}</p><small>{{ Number(summary.latest_adherence.completed) ? 'Registrada como realizada' : 'Registrada como não realizada' }} · {{ label(summary.latest_adherence.source) }}<br>{{ stamp(summary.latest_adherence.occurred_at) }} · {{ summary.latest_adherence.author_name }}</small></div></article></div>
        <section class="summary-block mt-3"><div class="section-heading mb-3"><h3 class="h6 mb-0">Últimas medições por indicador</h3><button class="btn btn-link btn-sm p-0" :disabled="busy" @click="open('indicators')">Ver histórico completo →</button></div><p v-if="!summary.indicators.total" class="text-secondary mb-0">Nenhum indicador cadastrado. Valores clínicos não são presumidos.</p><div v-else class="table-responsive"><table class="table summary-readings"><thead><tr><th>Indicador</th><th>Origem profissional</th><th>Origem autorrelatada</th></tr></thead><tbody><tr v-for="i in summary.indicators.items" :key="i.id"><td><button class="btn btn-link btn-sm p-0 text-start" :disabled="busy" @click="open('indicators', null, i.id)">{{ i.name }}</button><small class="d-block text-secondary">{{ i.unit }}</small></td><td v-for="source in ['professional', 'self_reported']" :key="source"><template v-if="i[source]"><strong>{{ value(i[source]) }} {{ i.unit }}</strong><small class="d-block">Coleta: {{ stamp(i[source].collected_at) }}</small><small class="d-block">{{ i[source].method }}</small><small class="d-block">{{ source === 'professional' ? i[source].professional_name : 'Registrado por ' + i[source].recorded_by_name }}</small></template><span v-else class="text-secondary">Sem medição desta origem</span></td></tr></tbody></table></div><p v-if="summary.indicators.total > summary.indicators.items.length" class="small text-secondary mt-2 mb-0">Exibindo {{ summary.indicators.items.length }} de {{ summary.indicators.total }} indicadores, pelas coletas mais recentes.</p></section>
        <section class="summary-block mt-3"><div class="section-heading mb-3"><h3 class="h6 mb-0">Metas dos planos ativos ou revisados</h3><button class="btn btn-link btn-sm p-0" :disabled="busy" @click="open('goals', summary.goals.items[0]?.plan_id)">Acompanhar metas →</button></div><p v-if="!summary.goals.total" class="text-secondary mb-0">Nenhuma meta ativa em plano ativo ou revisado.</p><div v-for="g in summary.goals.items" :key="g.id" class="summary-goal"><div><strong>{{ g.description }}</strong><p class="small text-secondary mb-1">{{ g.indicator?.name || 'Indicador não associado' }} · {{ label(g.direction) }} · alvo {{ formatarAlvo(g) }} {{ g.unit }}</p><small>Prazo: {{ formatDate(g.deadline) }} · {{ g.responsible_name }} · origem {{ label(g.indicator?.measurement_source) || 'não informada' }}</small></div><div class="summary-goal-state"><span class="status-badge" :class="g.progress.state">{{ label(g.progress.state) }}</span><small>{{ g.progress.samples }} de {{ g.min_samples }} medição(ões) mínimas</small><button class="btn btn-link btn-sm p-0" :disabled="busy" @click="open('goals', g.plan_id)">Abrir meta</button></div></div><p v-if="summary.goals.total > summary.goals.items.length" class="small text-secondary mt-2 mb-0">Exibindo {{ summary.goals.items.length }} de {{ summary.goals.total }} metas, pelos prazos mais próximos.</p></section>
        <details class="summary-history mt-3"><summary>Última revisão e encaminhamentos</summary><div class="pt-3"><template v-if="summary.latest_review"><h3 class="h6">Última revisão do plano</h3><p class="summary-authorship">{{ stamp(summary.latest_review.created_at) }} · {{ summary.latest_review.author_name }} · {{ label(summary.latest_review.outcome) }}</p><RecordText :text="summary.latest_review.notes" /><button class="btn btn-link btn-sm p-0 mt-2" :disabled="busy" @click="open('records', summary.latest_review.plan_id)">Ver revisão completa →</button></template><p v-else class="text-secondary">Nenhuma revisão registrada.</p><h3 class="h6 mt-4">Encaminhamentos recentes</h3><p v-if="!summary.recent_referrals.length" class="text-secondary">Nenhum encaminhamento registrado.</p><div v-for="r in summary.recent_referrals" :key="r.id" class="border-top py-3"><strong>{{ r.recipient_name }}</strong><p class="summary-authorship">{{ stamp(r.created_at) }} · {{ label(r.status) }}</p><RecordText :text="r.reason" /></div></div></details>
      </div>
    </template>
  </section>
</template>
